import unittest
from references import format_reference, format_external_reference

class ContractTests(unittest.TestCase):
    def test_public_contracts(self):
        for function in (format_reference, format_external_reference):
            for value, expected in ((None, ""), ("", ""), (" a  b ", "A--B"), ("straße", "STRASSE")):
                with self.subTest(function=function.__name__, value=value):
                    self.assertEqual(function(value), expected)
    def test_invalid_type(self):
        for function in (format_reference, format_external_reference):
            with self.assertRaises(AttributeError):
                function(12)

